<?php require __DIR__.'/../config/config.php';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$s=$pdo->prepare('SELECT * FROM admin WHERE username=?');$s->execute([trim($_POST['username']??'')]);$a=$s->fetch();if($a&&password_verify($_POST['password']??'',$a['password_hash'])){session_regenerate_id(true);$_SESSION['admin_id']=(int)$a['id'];header('Location: index.php');exit;}$err='Invalid admin login.';}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="../assets/css/app.css"><title>RAAZ Admin</title></head><body class="auth"><form class="authbox" method="post"><a class="logo">RAAZ<span>.</span> ADMIN</a><h1>Admin sign in</h1><?php if($err):?><p class="error"><?=e($err)?></p><?php endif?><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Username</label><input name="username" required><label>Password</label><input type="password" name="password" required><button class="primary">Sign in</button></form></body></html>